create table wksp_dtesc.sgt_interfaces (
    id                number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1
    cache 20 noorder nocycle nokeep noscale not null enable,
    equipo_id         number not null enable,
    nombre            varchar2(255 char) not null enable,
    etiqueta          varchar2(255 char),
    estado            varchar2(255 char) not null enable,
    tipo_interface_id number not null enable,
    tx_en_dbm         varchar2(10 char),
    rx_en_dbm         varchar2(10 char),
    mac_address       varchar2(25 char),
    creado_el         timestamp(6),
    actualizado_el    timestamp(6),
    actualizado_por   varchar2(255 byte),
    creado_por        varchar2(255 byte),
    velocidad_mbps    number,
    velocidad_mpbs    number
);

alter table wksp_dtesc.sgt_interfaces
    add constraint sgt_interfaces_estado_ck
        check ( estado in ( 'NA', 'UP', 'DOWN' ) ) enable;

alter table wksp_dtesc.sgt_interfaces add primary key ( id )
    using index enable;


